import{_ as o,a0 as s,w as r,s as u,I as p,a1 as i,A as a,x as e,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"图解 Debian 10（Buster）安装步骤 | LCTT x X-CMD","titleTemplate":false,"description":"图解 Debian 10（Buster）安装步骤 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"图解 Debian 10（Buster）安装步骤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"图解 Debian 10（Buster）安装步骤 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190708 Debian 10 (Buster) Installation Steps with Screenshots","title":"图解 Debian 10（Buster）安装步骤","tag":"201907","desc":""},"relativePath":"201907/20190708 Debian 10 (Buster) Installation Steps with Screenshots.md","filePath":"[post].md"}'),d={name:"201907/20190708 Debian 10 (Buster) Installation Steps with Screenshots.md"};function w(b,t,h,m,c,D){const n=s("Link");return r(),u("div",null,[p("p",null,[i(n,{href:"collector:",title:"lujun9972"},{default:a(()=>[...t[0]||(t[0]=[e("#",-1)])]),_:1}),t[5]||(t[5]=e(": subject: (Debian 10 (Buster) Installation Steps with Screenshots) ",-1)),i(n,{href:"collector:",title:"lujun9972"},{default:a(()=>[...t[1]||(t[1]=[e("#",-1)])]),_:1}),t[6]||(t[6]=e(": via: (",-1)),i(n,{href:"https://www.linuxtechi.com/debian-10-buster-installation-guide/"},{default:a(()=>[...t[2]||(t[2]=[e("https://www.linuxtechi.com/debian-10-buster-installation-guide/",-1)])]),_:1}),t[7]||(t[7]=e(") ",-1)),i(n,{href:"collector:",title:"lujun9972"},{default:a(()=>[...t[3]||(t[3]=[e("#",-1)])]),_:1}),t[8]||(t[8]=e(": author: (Pradeep Kumar ",-1)),i(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...t[4]||(t[4]=[e("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),t[9]||(t[9]=e(")",-1))]),t[26]||(t[26]=l('<h1 id="图解-debian-10-buster-安装步骤" tabindex="-1">图解 Debian 10（Buster）安装步骤 <a class="header-anchor" href="#图解-debian-10-buster-安装步骤" aria-label="Permalink to “图解 Debian 10（Buster）安装步骤”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201907/11/000856swbwnfyknnbn3twk.jpg" alt=""></p><p>Debian 项目发布了它的最新稳定版 Debian 10，其代号是 “Buster”，这个发布版将获得 5 年的支持。Debian 10 可用于 32 位和 64 位系统。这个发布版带来很多新的特色，列出下面一些特色：</p><ul><li>引入新的 Debian 10 的主题 “FuturePrototype”</li><li>新版本的电脑桌面环境 GNOME 3.30、Cinnamon 3.8、KDE Plasma 5.14、MATE 1.20、Xfce 4.12</li><li>长期支持版内核 4.19.0-4</li><li>新的 Python 3 (3.7.2)、Perl 5.28、PHP 7.3</li><li>iptables 替换为 nftables</li><li>更新 LibreOffice 6.1、GIMP 2.10.8</li><li>更新 OpenJDK 11、MariaDB 10.3 和 Apache 2.4.38</li><li>更新 Chromium 73.0、Firefox 60.7</li><li>改进 UEFI 支持</li></ul><p>在这篇文章中，我们将演示如何在你的笔记本电脑和台式电脑上安装 Debian 10 “Buster” 工作站。</p><p>Debian 10 建议系统要求：</p><ul><li>2 GB 内存</li><li>2 GHz 双核处理器</li><li>10 GB 可用硬盘空间</li><li>可启动安装介质（USB / DVD）</li><li>网络连接（可选）</li></ul><p>让我们跳转到 Debian 10 的安装步骤。</p><h3 id="步骤-1-下载-debian-10-iso-文件" tabindex="-1">步骤：1）下载 Debian 10 ISO 文件 <a class="header-anchor" href="#步骤-1-下载-debian-10-iso-文件" aria-label="Permalink to “步骤：1）下载 Debian 10 ISO 文件”">​</a></h3><p>从它的官方入口网站，下载 Debian 10 ISO 文件，</p>',10)),p("ul",null,[p("li",null,[i(n,{href:"https://www.debian.org/releases/buster/debian-installer/"},{default:a(()=>[...t[10]||(t[10]=[e("https://www.debian.org/releases/buster/debian-installer/",-1)])]),_:1})])]),t[27]||(t[27]=l('<p>ISO 文件下载完成后刻录它到 USB 或 DVD，使其可用来启动。</p><h3 id="步骤-2-使用安装可启动介质-usb-dvd-启动你的电脑系统" tabindex="-1">步骤：2）使用安装可启动介质（USB / DVD）启动你的电脑系统 <a class="header-anchor" href="#步骤-2-使用安装可启动介质-usb-dvd-启动你的电脑系统" aria-label="Permalink to “步骤：2）使用安装可启动介质（USB / DVD）启动你的电脑系统”">​</a></h3><p>重启你将安装 Debian 10 的电脑，转到 BIOS 设置，并设置启动介质为 USB 或 DVD。 用可启动介质启动电脑后，那么我们将看到下面的屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Choose-Graphical-Install-Debian-10.jpg" alt=""></p><p>选择第一个选项 “Graphical Install”。</p><h3 id="步骤-3-选择你的首选语言、位置和键盘布局" tabindex="-1">步骤：3）选择你的首选语言、位置和键盘布局 <a class="header-anchor" href="#步骤-3-选择你的首选语言、位置和键盘布局" aria-label="Permalink to “步骤：3）选择你的首选语言、位置和键盘布局”">​</a></h3><p>在这个步骤中，你将被要求选择你的首选语言。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Choose-Language-Debian10-Installation.jpg" alt=""></p><p>点击 “Continue”。</p><p>选择你的首选位置，电脑系统将依照位置自动设置时区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Select-Location-Debain10-Installation.jpg" alt=""></p><p>现在选择适合于你安装设备的键盘布局。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Keyboard-Layout-Debian10-Installation.jpg" alt=""></p><p>点击 “Continue” 以继续。</p><h3 id="步骤-4-为-debian-10-系统设置主机名称和域名" tabindex="-1">步骤：4）为 Debian 10 系统设置主机名称和域名 <a class="header-anchor" href="#步骤-4-为-debian-10-系统设置主机名称和域名" aria-label="Permalink to “步骤：4）为 Debian 10 系统设置主机名称和域名”">​</a></h3><p>设置适合于你的环境的主机名，然后在 “Continue” 上单击，就我而言, 我指定主机名为 “debian10-buster”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Hostname-During-Debian10-Installation.jpg" alt=""></p><p>指定适合于环境的域名，并安装，然后在 “Continue” 上单击。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Domain-Name-During-Debian10-Installation.jpg" alt=""></p><h3 id="步骤-5-指定-root-用户的密码" tabindex="-1">步骤：5）指定 root 用户的密码 <a class="header-anchor" href="#步骤-5-指定-root-用户的密码" aria-label="Permalink to “步骤：5）指定 root 用户的密码”">​</a></h3><p>在下面的屏幕中指定 root 密码，然后在 “Continue” 上单击。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Root-Password-Debian10-Installation.jpg" alt=""></p><h3 id="步骤-6-创建本地用户和它的密码" tabindex="-1">步骤：6）创建本地用户和它的密码 <a class="header-anchor" href="#步骤-6-创建本地用户和它的密码" aria-label="Permalink to “步骤：6）创建本地用户和它的密码”">​</a></h3><p>在这个步骤中，你将被提示指定本地用户具体信息，如完整的姓名、用户名和密码，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Local-User-FullName-Debian10.jpg" alt=""></p><p>在 “Continue” 上单击。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/UserName-LocalUser-Debian10-Installation.jpg" alt=""></p><p>在 “Continue” 上单击，并在接下来的窗口中指定密码。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Password-Localuser-Debian10.jpg" alt=""></p><h3 id="步骤-7-为-debian-10-选择硬盘分区方案" tabindex="-1">步骤：7）为 Debian 10 选择硬盘分区方案 <a class="header-anchor" href="#步骤-7-为-debian-10-选择硬盘分区方案" aria-label="Permalink to “步骤：7）为 Debian 10 选择硬盘分区方案”">​</a></h3><p>在这个步骤中，为 Debian 10 选择硬盘分区方案，就我而言，我有 40 GB 硬盘可用于操作系统安装。分区方案有两种类型：</p><ul><li>向导分区（安装器将自动创建需要的分区）</li><li>手动分区（正如名字所示，使用这种方式，我们可以手动创建分区方案）</li></ul><p>在这篇教程中，我们将在我 42 GB 硬盘上使用带有 LVM 的向导分区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Choose-Guided-Partitioning-Scheme-Debain10-Installation.jpg" alt=""></p><p>在 “Continue” 上单击来继续，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Hard-Disk-Debian10-Installation.jpg" alt=""></p><p>正如我们所视，我大约有 42 GB 硬盘空间，选择 “Continue”。</p><p>在接下来的屏幕中，你将被要求选择分区，如果是 Linux 新用户，那么选择第一个选项。假使你想要一个独立的 home 分区，那么选择第二种方案，否则选择第三种方案，它们将为 <code>/home</code>、<code>/var</code> 和 <code>/tmp</code> 创建独立的分区。</p><p>就我而言，我将通过选择第三种选项来为 <code>/home</code>、<code>/var</code> 和 <code>/tmp</code> 创建独立的分区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Guided-Separate-Partitions-Debian10-Installation.jpg" alt=""></p><p>在接下来的屏幕中，选择 “yes” 来将更改写到磁盘中，配置 LVM ，然后在 “Continue” 上单击。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Write-Changes-Disk-Debian10-Installation.jpg" alt=""></p><p>在接下来的屏幕中，将显示分区表，验证分区大小、文件系统类型和挂载点。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Debian10-Partition-Table.jpg" alt=""></p><p>在 “Continue” 上单击来继续，</p><p>在接下来的屏幕中，选择 “yes” 来写更改到磁盘中，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Choose-Yes-Write-Changes-Disk-Debian10-Installation.jpg" alt=""></p><p>在 “Continue” 上单击来继续安装，</p><h3 id="步骤-7-debian-10-安装开始" tabindex="-1">步骤：7）Debian 10 安装开始 <a class="header-anchor" href="#步骤-7-debian-10-安装开始" aria-label="Permalink to “步骤：7）Debian 10 安装开始”">​</a></h3><p>在这一步骤中，Debian 10 的安装已经开始，并正在进行中，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Debian10-Installation-Progress.jpg" alt=""></p><p>在安装期间，安装器将提示你扫描 CD/DVD 以配置软件包管理器，选择 “No” ，然后在 “Continue” 上单击。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Scan-DVD-Debian10-Installation.jpg" alt=""></p><p>在接下来的屏幕中，如果你想配置基于网络的软件包管理器选择 “yes” ，但是为了使这个方式工作，要确保你的系统连接到了网络，否则选择 “No”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Network-Mirror-Debian10-Package-Manager.jpg" alt=""></p><p>在 “Continue” 上单击来配置基于你本地的软件包管理器，在接下来的几个屏幕中，你将被提示选择本地和 Debian 软件包存储库 URL ，然后你将获得下面的屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Apt-Config-Debian10-Installation.jpg" alt=""></p><p>选择 “No” 来跳过软件包审查步骤，然后在 “Continue” 上单击。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Pkg-Survey-Debian10-Installation.jpg" alt=""></p><p>在接下来的窗口中，你将被提示选择电脑桌面环境和其它软件包，就我而言，我选择 “Gnome Desktop” ，“SSH Server” 和 “Standard System utilities”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Software-Selection-Debian10-Installation.jpg" alt=""></p><p>在 “Continue” 上单击来继续安装，</p><p>选择选项 “yes” 来安装 Grub 引导加载程序。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Install-Grub-Bootloader-Debian10-Installation.jpg" alt=""></p><p>在 “Continue” 上单击来继续，然后在接下来的窗口中选择将安装引导加载程序的磁盘（<code>/dev/sda</code>）。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Install-grub-on-dev-sda-debian10.jpg" alt=""></p><p>在 “Continue” 上单击来继续安装，一旦安装完成，安装器将提示我们来重启系统，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Installation-Completed-Debain10.jpg" alt=""></p><p>在 “Continue” 上单击来重启你的系统，不要忘记在 BIOS 设置中更改启动介质，以便系统从我们已经安装 Debian 10 操作系统的硬盘启动。</p><h3 id="步骤-8-启动你新安装的-debian-10-系统" tabindex="-1">步骤：8）启动你新安装的 Debian 10 系统 <a class="header-anchor" href="#步骤-8-启动你新安装的-debian-10-系统" aria-label="Permalink to “步骤：8）启动你新安装的 Debian 10 系统”">​</a></h3><p>在成功安装后，一旦我们重启系统，我们将获取下面的引导加载程序屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Bootloader-Screen-Debian10.jpg" alt=""></p><p>选择第一个选项 “Debian GNU/Linux” 并敲击回车键。</p><p>一旦系统启动，使用我在安装期间创建的本地用户和它的密码。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Local-User-Debian10-Login.jpg" alt=""></p><p>在成功登录后，将看到如下电脑桌面屏幕，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Desktop-Screen-Debian10-Buster.jpg" alt=""></p><p>这证实 Debian 10 已经成功安装，这就是本文的全部，探索这个令人激动的 Linux 发行版吧，玩得开心 😊</p><hr>',79)),p("p",null,[t[12]||(t[12]=e("via: ",-1)),i(n,{href:"https://www.linuxtechi.com/debian-10-buster-installation-guide/"},{default:a(()=>[...t[11]||(t[11]=[e("https://www.linuxtechi.com/debian-10-buster-installation-guide/",-1)])]),_:1})]),p("p",null,[t[17]||(t[17]=e("作者：",-1)),i(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...t[13]||(t[13]=[e("Pradeep Kumar",-1)])]),_:1}),t[18]||(t[18]=e(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[14]||(t[14]=[e("lujun9972",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),i(n,{href:"https://github.com/robsean"},{default:a(()=>[...t[15]||(t[15]=[e("robsean",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[23]||(t[23]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:a(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const C=o(d,[["render",w]]);export{f as __pageData,C as default};
